<script setup lang="ts">
import {trapDialogFocus} from "../../services/dialogFocus";
import {computed,onBeforeUnmount,ref} from 'vue';
import {onBeforeRouteLeave,useRoute} from 'vue-router';
import {useI18n} from 'vue-i18n';
import {API_URL} from '../../services/api';
import {operationRequest} from '../../services/admin/operations';
import {calendarRange,shiftDay,transitions,type CalendarMode} from '../../services/admin/calendar';
import {clinicDate,dateLabel,timeLabel} from '../../services/booking/calendar';
import {createBookingAPI,validReceipt} from '../../services/booking/api';
import {validateContact} from '../../services/booking/flow';
import type {Contact,Catalog,Doctor,Slot} from '../../services/booking/types';
import BookingContactFields from '../../components/booking/BookingContactFields.vue';
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue';
const route=useRoute();let openedFromRoute=false;
const {t,locale}=useI18n(),api=createBookingAPI(API_URL||'');
const mode=ref<CalendarMode>(window.matchMedia('(max-width:600px)').matches?'day':'week'),date=ref(clinicDate()),doctorFilter=ref(''),serviceFilter=ref(''),statusFilter=ref(''),search=ref(''),offset=ref(0),more=ref(false);
const rows=ref<any[]>([]),doctors=ref<any[]>([]),services=ref<any[]>([]),catalog=ref<Catalog|null>(null),busy=ref(false),error=ref(''),notice=ref('');
const selectedRange=ref(calendarRange(date.value,mode.value));
const range=computed(()=>selectedRange.value);
const dialog=ref<HTMLDialogElement>(),detail=ref<any>(null),history=ref<any[]>([]),editing=ref(false),moving=ref(false),formService=ref(''),formDoctor=ref(''),formDate=ref(clinicDate()),slots=ref<Slot[]|null>(null),chosen=ref<Slot|null>(null);
const contact=ref<Contact>({first_name:'',last_name:'',email:'',phone:''}),consent=ref(false),errors=ref<Record<string,string>>({}),pending=ref<{key:string;body:any}|null>(null);
let controller=new AbortController(),choiceSerial=0;
const serviceName=(id:string)=>services.value.find(s=>s.id===id)?.['name_'+locale.value]||t('operations.archivedService');
const doctorName=(id:string)=>doctors.value.find(d=>d.id===id)?.name||t('operations.archivedDoctor');
const visits=(day:string)=>rows.value.filter(row=>clinicDate(new Date(row.starts_at))===day).sort((a,b)=>Date.parse(a.starts_at)-Date.parse(b.starts_at));
const eligibleServices=ref<Catalog['services']>([]);
const configuredDoctors=ref<Doctor[]>([]);
const canAdd=computed(()=>!!catalog.value?.privacy_notice_version&&configuredDoctors.value.length>0);
const monthOffset=computed(()=>(new Date(range.value.from+'T12:00:00Z').getUTCDay()+6)%7);
async function navigate(direction:number){if(mode.value==='month'){const d=new Date(date.value.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+direction);date.value=d.toISOString().slice(0,10)}else date.value=shiftDay(date.value,direction*(mode.value==='week'?7:1));await load()}
async function today(){date.value=clinicDate();await load()}
async function openDay(day:string){date.value=day;await view('day')}
async function selectDoctor(){const serial=++choiceSerial;chosen.value=null;slots.value=null;eligibleServices.value=[];try{const results=await Promise.all((catalog.value?.services||[]).map(async s=>({service:s,doctors:await api.doctors(s.id,controller.signal)})));if(serial!==choiceSerial)return;eligibleServices.value=results.filter(r=>r.doctors.some(d=>d.id===formDoctor.value)).map(r=>r.service);if(!eligibleServices.value.some(s=>s.id===formService.value))formService.value=eligibleServices.value[0]?.id||''}catch{if(serial===choiceSerial)error.value='unavailable'}}
async function load(reset=true){if(reset)offset.value=0;busy.value=true;error.value='';controller.abort();controller=new AbortController();const own=controller;selectedRange.value=calendarRange(date.value,mode.value);
 try{const [result,options,currentCatalog]=await Promise.all([operationRequest('/booking/appointments/search',own.signal,{date_from:range.value.from,date_to:range.value.to,doctor_id:doctorFilter.value,service_id:serviceFilter.value,status:statusFilter.value,search:search.value,offset:offset.value},'POST'),operationRequest('/operations/appointments/options',own.signal),api.services(own.signal).catch(()=>null)]);if(!own.signal.aborted){rows.value=result.appointments;more.value=result.has_more;doctors.value=options.doctors;services.value=options.services;catalog.value=currentCatalog;configuredDoctors.value=[];if(currentCatalog?.services.length){const lists=await Promise.all(currentCatalog.services.map(s=>api.doctors(s.id,own.signal)));if(own.signal.aborted)return;configuredDoctors.value=[...new Map(lists.flat().map(d=>[d.id,d])).values()]}if(route.meta.createAppointment&&!openedFromRoute){openedFromRoute=true;if(canAdd.value)await begin()}}}catch{if(!own.signal.aborted)error.value='unavailable'}finally{if(!own.signal.aborted)busy.value=false}}
async function view(next:CalendarMode){mode.value=next;await load()}
async function show(id:string){busy.value=true;error.value='';try{const [row,events]=await Promise.all([operationRequest('/booking/appointments/'+id,controller.signal),operationRequest('/booking/appointments/'+id+'/history',controller.signal)]);detail.value=row;history.value=events.events;editing.value=false;moving.value=false;if(!dialog.value?.open)dialog.value?.showModal()}catch{error.value='unavailable'}finally{busy.value=false}}
function canClose(){return !editing.value||window.confirm(t(pending.value?'operations.uncertain':'operations.discard'))}
function close(){if(busy.value||!canClose())return;dialog.value?.close();detail.value=null;history.value=[];editing.value=false;pending.value=null;contact.value={first_name:'',last_name:'',email:'',phone:''};chosen.value=null;choiceSerial++}
async function begin(move=false){if(!catalog.value?.privacy_notice_version)return;moving.value=move;editing.value=true;pending.value=null;errors.value={};consent.value=false;chosen.value=null;slots.value=null;formService.value=move?detail.value.service_id:catalog.value.services[0]?.id||'';formDate.value=move?clinicDate(new Date(detail.value.starts_at)):clinicDate();formDoctor.value=move?detail.value.doctor_id:configuredDoctors.value[0]?.id||'';if(!move){detail.value=null;history.value=[];contact.value={first_name:'',last_name:'',email:'',phone:''};if(!dialog.value?.open)dialog.value?.showModal()}await selectDoctor()}
async function times(){const serial=++choiceSerial;slots.value=null;chosen.value=null;busy.value=true;error.value='';try{const query=`service_id=${formService.value}&doctor_id=${formDoctor.value}&date=${formDate.value}`;const result=moving.value?await operationRequest('/booking/appointments/'+detail.value.id+'/availability?'+query,controller.signal):await api.availability(formService.value,formDoctor.value,formDate.value,controller.signal);if(serial===choiceSerial)slots.value=result.slots}catch{if(serial===choiceSerial)error.value='unavailable'}finally{busy.value=false}}
async function save(){if(busy.value)return;errors.value=moving.value?{}:validateContact(contact.value,consent.value);if(Object.keys(errors.value).length||(!chosen.value&&!pending.value))return;busy.value=true;error.value='';
 try{let result;if(moving.value){result=await operationRequest('/booking/appointments/'+detail.value.id+'/reschedule',controller.signal,{service_id:formService.value,doctor_id:formDoctor.value,starts_at:chosen.value!.starts_at,expected_version:detail.value.version},'POST')}else{if(!pending.value)pending.value={key:crypto.randomUUID(),body:{...contact.value,service_id:formService.value,doctor_id:formDoctor.value,starts_at:chosen.value!.starts_at,privacy_acknowledged:true,privacy_notice_version:catalog.value!.privacy_notice_version}};result=await operationRequest('/booking/appointments',controller.signal,pending.value.body,'POST',pending.value.key)}if(!validReceipt(result))throw Error('unavailable');pending.value=null;editing.value=false;dialog.value?.close();contact.value={first_name:'',last_name:'',email:'',phone:''};await load();notice.value=t('operations.saved')+' '+result.booking_reference;await show(result.id)}catch(e){error.value=(e as Error).message==='conflict'?'conflict':(e as Error).message==='invalid'?'invalid':'unavailable';if(['conflict','invalid'].includes(error.value)&&!moving.value)pending.value=null}finally{busy.value=false}}
async function changeStatus(to:string){if(!window.confirm(t('operations.confirmAction')))return;busy.value=true;error.value='';try{await operationRequest('/booking/appointments/'+detail.value.id+'/status',controller.signal,{status:to,expected_version:detail.value.version},'PATCH');const id=detail.value.id;await load();await show(id)}catch(e){error.value=(e as Error).message==='conflict'?'conflict':'unavailable'}finally{busy.value=false}}
function unload(e:BeforeUnloadEvent){if(editing.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',unload);onBeforeRouteLeave(()=>canClose());onBeforeUnmount(()=>{controller.abort();choiceSerial++;rows.value=[];detail.value=null;contact.value={first_name:'',last_name:'',email:'',phone:''};window.removeEventListener('beforeunload',unload)});void load();
</script>
<template>
<section class="appointments"><AdminPageHeader :title="t('operations.appointments')"><template #actions><button :aria-describedby="!canAdd?'appointment-setup':undefined" :disabled="busy||!canAdd" @click="begin()">{{t('operations.manual')}}</button></template></AdminPageHeader><p v-if="!busy&&!canAdd" id="appointment-setup" class="setup-notice">{{t('operations.setup')}} <RouterLink to="/admin/doctors">{{t('operations.doctorName')}}</RouterLink></p>
<div class="calendar-toolbar"><div class="actions"><button v-for="v in ['day','week','month'] as CalendarMode[]" :key="v" :aria-pressed="mode===v" :disabled="busy" @click="view(v)">{{t('operations.'+v)}}</button></div><div class="actions"><button :disabled="busy" @click="navigate(-1)">{{t('operations.previous')}}</button><button :disabled="busy" @click="today">{{t('operations.today')}}</button><button :disabled="busy" @click="navigate(1)">{{t('operations.next')}}</button></div></div>
<form class="filters" @submit.prevent="load()"><label>{{t('operations.date')}}<input v-model="date" type="date" required :disabled="busy" @change="date&&load()"/></label><label>{{t('operations.doctorName')}}<select :aria-label="t('operations.doctorName')" v-model="doctorFilter" :disabled="busy" @change="load()"><option value="">{{t('operations.all')}}</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label><details class="advanced"><summary>{{t('simple.advanced')}}</summary><label>{{t('operations.services')}}<select v-model="serviceFilter"><option value="">{{t('operations.all')}}</option><option v-for="s in services" :key="s.id" :value="s.id">{{s['name_'+locale]}}</option></select></label><label>{{t('operations.status')}}<select v-model="statusFilter"><option value="">{{t('operations.all')}}</option><option v-for="s in ['pending','confirmed','completed','cancelled','rejected','no_show']" :key="s" :value="s">{{t('operations.'+s)}}</option></select></label><label>{{t('operations.search')}}<input v-model="search" type="search" maxlength="100" autocomplete="off"/></label><button :disabled="busy">{{t('operations.applyFilters')}}</button></details></form>
<p v-if="busy||notice" role="status">{{busy?t('operations.loading'):notice}}</p><p v-if="error&&!dialog?.open" role="alert">{{t(error==='unavailable'?'operations.calendarUnavailable':'operations.'+error)}}</p><p class="calendar-period">{{dateLabel(range.from,locale)}}<template v-if="range.from!==range.to"> — {{dateLabel(range.to,locale)}}</template><small>{{t('operations.riga')}}</small></p>
<p v-if="more||offset>0" role="status">{{t('operations.pageNotice')}}</p>
<p v-if="!busy&&!error&&!rows.length" class="empty-period">{{t('operations.noVisits')}}</p>
<div v-if="mode==='month'" class="month-grid"><span v-for="n in 7" :key="'weekday'+n" class="weekday">{{new Intl.DateTimeFormat(locale,{weekday:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,9,5+n-1)))}}</span><span v-for="n in monthOffset" :key="'blank'+n"/><button v-for="day in range.days" :key="day" :disabled="busy" :aria-label="dateLabel(day,locale)+', '+visits(day).length+' '+t('operations.appointments')" :aria-current="day===clinicDate()?'date':undefined" @click="openDay(day)"><strong>{{Number(day.slice(-2))}}</strong><span v-if="visits(day).length">{{visits(day).length}}</span></button></div>
<div v-else :class="['visit-grid',mode]"><section v-for="day in range.days" :key="day"><h2>{{mode==='week'?new Intl.DateTimeFormat(locale,{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z')):dateLabel(day,locale)}}</h2><button v-for="visit in visits(day)" :key="visit.id" class="visit" :data-status="visit.status" :disabled="busy" @click="show(visit.id)"><strong class="visit-time">{{timeLabel(visit.starts_at,locale)}}–{{timeLabel(visit.ends_at,locale)}}</strong><strong class="visit-patient">{{visit.first_name}} {{visit.last_name}}</strong><span class="visit-service">{{serviceName(visit.service_id)}}</span><span class="visit-doctor">{{doctorName(visit.doctor_id)}}</span><span class="visit-status">{{t('operations.'+visit.status)}}</span></button></section></div>
<div class="actions"><button v-if="offset>0" :disabled="busy" @click="()=>{offset=Math.max(0,offset-100);load(false)}">{{t('operations.previous')}}</button><button v-if="more" :disabled="busy" @click="()=>{offset+=100;load(false)}">{{t('operations.next')}}</button></div>
<dialog @keydown="trapDialogFocus" :aria-label="t('operations.appointments')" ref="dialog" @cancel.prevent="close"><div class="actions"><button :disabled="busy" @click="close">{{t('operations.close')}}</button></div><p v-if="error" role="alert">{{t(error==='unavailable'?'operations.calendarUnavailable':'operations.'+error)}}</p>
<template v-if="detail&&!editing"><h2>{{detail.first_name}} {{detail.last_name}}</h2><p>{{detail.booking_reference}} · {{t('operations.'+detail.status)}}</p><p>{{dateLabel(clinicDate(new Date(detail.starts_at)),locale)}} · {{timeLabel(detail.starts_at,locale)}}–{{timeLabel(detail.ends_at,locale)}}</p><p>{{serviceName(detail.service_id)}} · {{doctorName(detail.doctor_id)}}</p><p>{{detail.phone}} · {{detail.email}}</p><div class="actions"><button v-if="['pending','confirmed'].includes(detail.status)" :disabled="busy||!canAdd" @click="begin(true)">{{t('operations.reschedule')}}</button><button v-for="action in transitions(detail.status).filter(s=>['confirmed','cancelled'].includes(s))" :key="action" :disabled="busy||(action==='completed'&&Date.parse(detail.ends_at)>Date.now())||(action==='no_show'&&Date.parse(detail.starts_at)>Date.now())" @click="changeStatus(action)">{{t(action==='confirmed'?'operations.confirmVisit':'operations.cancelVisit')}}</button></div><details><summary>{{t('simple.advanced')}}</summary><div class="actions"><button v-for="action in transitions(detail.status).filter(s=>!['confirmed','cancelled'].includes(s))" :key="action" :disabled="busy||(action==='completed'&&Date.parse(detail.ends_at)>Date.now())||(action==='no_show'&&Date.parse(detail.starts_at)>Date.now())" @click="changeStatus(action)">{{t('operations.'+action)}}</button></div></details><details><summary>{{t('operations.history')}}</summary><ol><li v-for="event in history" :key="event.id">{{new Date(event.created_at).toLocaleString(locale,{timeZone:'Europe/Riga'})}} · {{t('operations.'+event.event_type)}}</li></ol></details></template>
<form v-if="editing" @submit.prevent="save"><h2>{{t(moving?'operations.reschedule':'operations.manual')}}</h2><fieldset :disabled="busy||!!pending"><label>{{t('operations.doctorName')}}<select :aria-label="t('operations.doctorName')" v-model="formDoctor" required @change="selectDoctor"><option v-for="d in configuredDoctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>{{t('operations.services')}}<select v-model="formService" required @change="()=>{chosen=null;slots=null}"><option v-for="s in eligibleServices" :key="s.id" :value="s.id">{{s['name_'+locale as keyof typeof s]}}</option></select></label><label>{{t('operations.date')}}<input v-model="formDate" type="date" required @change="()=>{chosen=null;slots=null}"/></label><button type="button" :disabled="!formDoctor||!formService" @click="times">{{t('operations.previewAvailability')}}</button><p v-if="slots?.length===0">{{t('operations.noSlots')}}</p><div class="slot-grid"><button v-for="slot in slots" :key="slot.starts_at" type="button" :aria-pressed="chosen?.starts_at===slot.starts_at" @click="chosen=slot">{{timeLabel(slot.starts_at,locale)}}</button></div><template v-if="!moving&&(chosen||pending)"><BookingContactFields v-model="contact" :errors="errors" :disabled="busy||!!pending"/><label><input v-model="consent" type="checkbox" required/>{{t('operations.patientConsent')}}</label><RouterLink to="/privatuma-politika" target="_blank">{{t('booking.privacyLink')}}</RouterLink><p v-if="errors.privacy" role="alert">{{t('booking.validation_privacy')}}</p></template></fieldset><p v-if="pending">{{t('operations.uncertain')}}</p><button :disabled="busy||(!chosen&&!pending)" type="submit">{{t(pending?'booking.retry':'operations.save')}}</button></form>
</dialog></section>
</template>
<style scoped>
.appointments{max-width:1500px}.actions,.slot-grid{display:flex;gap:10px;flex-wrap:wrap}.appointments button{font:inherit;min-height:44px;border:1px solid var(--line);padding:10px 14px;background:transparent;color:var(--ink);cursor:pointer}.appointments button:disabled{opacity:.5;cursor:default}.appointments [aria-pressed=true]{background:var(--ink);color:var(--white)}.filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.appointments label{display:block;margin:12px 0}.appointments input:not([type=checkbox]),.appointments select{display:block;min-height:44px;width:100%;font:inherit;padding:9px;border:1px solid var(--line);color:var(--ink);background:var(--white)}.visit-grid.week,.visit-grid.month{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}.visit-grid>section{padding:12px 0;border-top:1px solid var(--line);min-width:0}.visit-grid h2{font-size:15px}.visit{display:block;text-align:left;width:100%;margin:8px 0;overflow-wrap:anywhere}.visit span{display:block;font-size:12px;margin-top:6px}.appointments dialog{width:min(760px,calc(100vw - 24px));max-height:90dvh;margin:auto;padding:24px;border:1px solid var(--line);background:var(--white);color:var(--ink)}.appointments dialog::backdrop{background:rgb(20 30 20 / 45%)}.appointments fieldset{border:0;padding:0;min-width:0}.appointments :focus-visible{outline:2px solid var(--ink);outline-offset:3px}[role=alert]{color:#8b3429}@media(max-width:1024px){.visit-grid.week,.visit-grid.month{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.filters,.visit-grid.week,.visit-grid.month{grid-template-columns:1fr}.appointments dialog{padding:16px}}
.calendar-toolbar{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.advanced{grid-column:1/-1}.appointments summary{cursor:pointer;min-height:44px;padding:12px 0}.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}.month-grid button{text-align:left;min-height:90px;padding:8px;min-width:0}.month-grid button span{display:block;font-size:11px;overflow-wrap:anywhere}.weekday{text-align:center;font-size:12px}.month-grid [aria-current=date]{border:2px solid var(--ink)}.empty-period{padding:24px 0}.setup-notice{font-size:14px}.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.appointments dialog details{border-top:1px solid var(--line);margin-top:18px}@media(max-width:600px){.filters{grid-template-columns:1fr}.month-grid button{padding:4px;min-height:64px}.month-grid button span{font-size:9px}.calendar-toolbar .actions{gap:6px}.visit-grid.week{grid-template-columns:1fr}}
.appointments :deep(.admin-page-heading){margin-bottom:20px;gap:12px}.appointments :deep(.admin-heading-actions button){background:var(--ink);color:var(--white)}.filters{margin:12px 0;gap:8px 14px}.filters label{margin:4px 0}.calendar-period{margin:12px 0;font-size:15px}.calendar-period small{display:block;font-size:11px;color:#596451;margin-top:2px}.visit-time{font-variant-numeric:tabular-nums;font-size:13px;display:block}.visit-patient{display:block;margin-top:4px;font-size:14px}.appointments .visit{padding:10px;border-left:3px solid #61765b}.visit-status{font-weight:600}.visit[data-status=pending]{border-left-color:#967230}.visit[data-status=cancelled],.visit[data-status=rejected]{border-left-color:#93978e;background:#edeee8}.visit[data-status=cancelled] .visit-time{text-decoration:line-through}.visit-grid.day .visit{display:grid;grid-template-columns:110px 1fr 1fr;gap:4px 16px;align-items:center}.visit-grid.day .visit-time{grid-row:1/3}.visit-grid.day .visit-patient,.visit-grid.day .visit span{margin:0}.month-grid button span{font-size:12px;font-weight:600;display:flex;align-items:center;gap:4px}.month-grid button span::before{content:'';width:4px;height:4px;border-radius:50%;background:currentColor;flex-shrink:0}.weekday{overflow:hidden;white-space:nowrap}@media(max-width:600px){.appointments :deep(.admin-page-heading h1){font-size:32px}.appointments :deep(.admin-page-heading){margin-bottom:16px}.filters{gap:6px;margin:10px 0}.visit-grid.day .visit{grid-template-columns:90px 1fr;gap:4px 8px}.visit-grid.day .visit-time{grid-row:1/5}.calendar-period{font-size:13px}.month-grid button span{font-size:12px}}
.appointments dialog h2{font-size:32px;line-height:1.2;margin:12px 0}.appointments dialog p{margin:12px 0}@media(max-width:600px){.calendar-toolbar{display:grid;grid-template-columns:1fr;width:100%}.calendar-toolbar .actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.calendar-toolbar button{font-size:12px;padding:8px 4px}.appointments dialog h2{font-size:28px}}
</style>
